"""course_codes.py - pulls apart section codes such as COP1035-02 and COP1035L-01."""


def prefix(code):
    """Return the three-letter subject prefix, e.g. 'COP'."""
    return code[:3]


def course_number(code):
    """Return the four-digit course number as a string, e.g. '1035'."""
    return code[3:7]


def level(code):
    """Return the course level as an int, e.g. 1 for COP1035."""
    return int(code[3])


def section(code):
    """Return the two-digit section, e.g. '02'."""
    return code[-2:]


def is_lab(code):
    """Return True if the code is a lab section."""
    return "L-" in code


def describe(code):
    """Given: builds a one-line label from the functions above."""
    label = prefix(code) + " " + course_number(code) + ", section " + section(code)
    if is_lab(code):
        label += " (lab)"
    return label

"""caesar.py - Caesar cipher for the Cybersecurity Club's clues."""

ALPHABET_SIZE = 26


def encrypt(text, distance):
    """Return text with each lowercase letter shifted distance places to the right."""
    code = ""
    for ch in text:
        if 'a' <= ch <= 'z':
            offset = ord(ch) - ord('a')
            cipher_value = ord('a') + (offset + distance) % ALPHABET_SIZE
            code += chr(cipher_value)
        else:
            code += ch
    return code


def decrypt(text, distance):
    """Return the original text from a clue made by encrypt(text, distance)."""
    return encrypt(text, -distance)

"""bases.py - converts between decimal and bases 2 to 16 for the network lab."""

DIGITS = "0123456789ABCDEF"


def digit_value(ch):
    """Given: the value of one digit character, e.g. '7' -> 7, 'F' or 'f' -> 15."""
    return DIGITS.find(ch.upper())


def to_decimal(digits, base):
    """Return the int that the string digits represents in base (2 to 16)."""
    decimal = 0
    exponent = len(digits) - 1
    for ch in digits:
        decimal += digit_value(ch) * base ** exponent
        exponent -= 1
    return decimal


def from_decimal(number, base):
    """Return the digit string that represents number (0 or more) in base (2 to 16)."""
    if number == 0:
        return "0"
    result = ""
    while number > 0:
        remainder = number % base
        number = number // base
        result = DIGITS[remainder] + result
    return result

