"""submissions.py - tidies uploaded file names and reflections for grading."""

ACCEPTED = ["py", "txt"]


def clean_name(raw):
    """Return raw without outer spaces, in lowercase, with inner spaces as underscores."""
    return raw.strip().lower().replace(" ", "_")


def extension(filename):
    """Return the lowercase extension after the last dot, or "" if there is none."""
    if "." not in filename:
        return ""
    return filename.split(".")[-1].lower()


def count_words(text):
    """Return the number of words in text."""
    return len(text.split())


def is_accepted(filename):
    """Given: True if the upload is a type the assignment accepts."""
    return extension(clean_name(filename)) in ACCEPTED

"""score_log.py - keeps quiz scores in a text file, one per line."""
import os


def save_scores(filename, scores):
    """Write each score on its own line, replacing anything already in the file."""
    f = open(filename, 'w')
    for score in scores:
        f.write(str(score) + '\n')
    f.close()


def average_score(filename):
    """Return the average of the scores in the file, rounded to 1 decimal.

    Returns None if the file does not exist or contains no scores.
    """
    if not os.path.exists(filename):
        return None
    f = open(filename, 'r')
    total = 0
    count = 0
    for line in f:
        for word in line.split():
            total += int(word)
            count += 1
    f.close()
    if count == 0:
        return None
    return round(total / count, 1)


def add_score(filename, score):
    """Add one score at the end of the file, keeping the scores already there."""
    f = open(filename, 'a')
    f.write(str(score) + '\n')
    f.close()


def summary(filename):
    """Given: a one-line report built from average_score."""
    average = average_score(filename)
    if average is None:
        return filename + ": no scores yet"
    return filename + ": average " + str(average)
